fn fib(n: u32) -> u64 {
    match n {
        0 => 0,
        1 => 1,
        _ => fib(n - 1) + fib(n - 2),
    }
}

fn is_palindrome(s: &str) -> bool {
    let cs: Vec<char> = s.chars().collect();
    cs.iter().eq(cs.iter().rev())
}

#[inline]
fn clamp(x: i32, lo: i32, hi: i32) -> i32 {
    x.max(lo).min(hi)
}
